/**
 * Volunteer survey cleaner.
 *
 * Sheets used:
 *   Raw     - source data, columns A:F = Timestamp, Name, Email,
 *             JoinedBefore, Phone, PreferredPark. Never modified.
 *   ParkMap - key -> canonical name. Created with starter rows if missing.
 *   Cleaned - full output with helper columns and flags.
 *   Final   - rows where FinalFlag=OK and Superseded is blank.
 *
 * Idempotent: Cleaned and Final are rebuilt on every run. Raw and
 * existing ParkMap rows are never touched.
 *
 * To run:
 *   1. Extensions > Apps Script, paste this file, Save.
 *   2. Reload the spreadsheet; use the Cleaning menu, or run
 *      cleanVolunteerData from the Apps Script editor.
 */

const RAW_SHEET     = 'Raw';
const PARKMAP_SHEET = 'ParkMap';
const CLEANED_SHEET = 'Cleaned';
const FINAL_SHEET   = 'Final';

// Window for "same name, near-identical timestamp" duplicate detection.
const DUP_MINUTES = 10;

// Starter mapping. Add more rows in the ParkMap sheet as you find variants.
// Keys must be lowercase a-z only (non-letters are stripped before lookup).
const PARKMAP_STARTER = [
  ['key',        'canonical'],
  ['westside',   'West Side'],
  ['wside',      'West Side'],
  ['northpark',  'North Park'],
  ['northpk',    'North Park'],
];

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Cleaning')
    .addItem('Run full clean', 'cleanVolunteerData')
    .addToUi();
}

function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  const raw = ss.getSheetByName(RAW_SHEET);
  if (!raw) throw new Error(`Sheet "${RAW_SHEET}" not found.`);

  const parkMap = loadOrCreateParkMap_(ss);
  const rawRows = readRaw_(raw);
  const cleanedRows = rawRows.map(r => cleanRow_(r, parkMap));

  // Duplicate detection needs the full set, so do it after per-row cleaning.
  annotateDuplicates_(cleanedRows);
  annotateFinalFlag_(cleanedRows);

  writeCleanedSheet_(ss, cleanedRows);
  writeFinalSheet_(ss, cleanedRows);

  SpreadsheetApp.getActive().toast(
    `Cleaned ${cleanedRows.length} rows. See "${CLEANED_SHEET}" and "${FINAL_SHEET}".`
  );
}

// ---------- ParkMap ----------

function loadOrCreateParkMap_(ss) {
  let sheet = ss.getSheetByName(PARKMAP_SHEET);
  if (!sheet) {
    sheet = ss.insertSheet(PARKMAP_SHEET);
    sheet.getRange(1, 1, PARKMAP_STARTER.length, 2).setValues(PARKMAP_STARTER);
    sheet.getRange(1, 1, 1, 2).setFontWeight('bold');
  }
  const last = sheet.getLastRow();
  const map = {};
  if (last < 2) return map;

  const values = sheet.getRange(2, 1, last - 1, 2).getValues();
  for (const [key, canonical] of values) {
    const k = String(key || '').trim().toLowerCase();
    const c = String(canonical || '').trim();
    if (k && c) map[k] = c;
  }
  return map;
}

// ---------- Read & clean ----------

function readRaw_(raw) {
  const last = raw.getLastRow();
  if (last < 2) return [];
  // Read 6 columns regardless of trailing blanks so indexes are stable.
  const values = raw.getRange(2, 1, last - 1, 6).getValues();
  return values.map((row, i) => ({
    rowNum:        i + 2,
    rawTimestamp:  row[0],
    rawName:       row[1],
    rawEmail:      row[2],
    rawJoined:     row[3],
    rawPhone:      row[4],
    rawPark:       row[5],
  }));
}

function cleanRow_(r, parkMap) {
  return {
    ...r,
    joinedClean:    normalizeYesNo_(r.rawJoined),
    phoneClean:     normalizePhone_(r.rawPhone),
    timestampClean: normalizeTimestamp_(r.rawTimestamp),
    parkClean:      normalizePark_(r.rawPark, parkMap),
    emailKey:       String(r.rawEmail || '').trim().toLowerCase(),
    nameKey:        String(r.rawName  || '').trim().toLowerCase().replace(/\s+/g, ' '),
    // Filled in by annotate* steps:
    dupEmail:   '',
    dupNameTs:  '',
    superseded: '',
    finalFlag:  '',
  };
}

function normalizeYesNo_(v) {
  const s = String(v == null ? '' : v).trim().toLowerCase();
  if (!s) return 'REVIEW';
  if (/^y(es)?$/.test(s)) return 'Yes';
  if (/^no?$/.test(s))    return 'No';
  return 'REVIEW';
}

function normalizePhone_(v) {
  const s = String(v == null ? '' : v);
  if (!s.trim()) return 'REVIEW';
  let digits = s.replace(/\D/g, '');
  if (digits.length === 11 && digits.startsWith('1')) digits = digits.slice(1);
  return digits.length === 10 ? digits : 'REVIEW';
}

function normalizeTimestamp_(v) {
  if (v instanceof Date && !isNaN(v)) return v;
  const s = String(v == null ? '' : v).trim();
  if (!s) return 'REVIEW';
  const parsed = new Date(s);
  return isNaN(parsed) ? 'REVIEW' : parsed;
}

function normalizePark_(v, parkMap) {
  const s = String(v == null ? '' : v).trim();
  if (!s) return 'REVIEW';
  const key = s.toLowerCase().replace(/[^a-z]/g, '');
  return parkMap[key] || 'REVIEW';
}

// ---------- Duplicate detection ----------

function annotateDuplicates_(rows) {
  // Count emails once, then flag any row whose email appears >1 times.
  const emailCounts = {};
  for (const r of rows) {
    if (r.emailKey) emailCounts[r.emailKey] = (emailCounts[r.emailKey] || 0) + 1;
  }
  for (const r of rows) {
    if (r.emailKey && emailCounts[r.emailKey] > 1) r.dupEmail = 'DUP-email';
  }

  // Name + timestamp within DUP_MINUTES (both sides of a near-pair get flagged).
  const windowMs = DUP_MINUTES * 60 * 1000;
  for (let i = 0; i < rows.length; i++) {
    const a = rows[i];
    if (!a.nameKey || !(a.timestampClean instanceof Date)) continue;
    for (let j = 0; j < rows.length; j++) {
      if (i === j) continue;
      const b = rows[j];
      if (b.nameKey !== a.nameKey) continue;
      if (!(b.timestampClean instanceof Date)) continue;
      if (Math.abs(a.timestampClean - b.timestampClean) <= windowMs) {
        a.dupNameTs = 'DUP-name-time';
        break;
      }
    }
  }

  // Per email, keep the row with the latest valid timestamp; mark the rest SUPERSEDED.
  const latestByEmail = {};
  for (const r of rows) {
    if (!r.emailKey || !(r.timestampClean instanceof Date)) continue;
    const prev = latestByEmail[r.emailKey];
    if (!prev || r.timestampClean > prev.timestampClean) latestByEmail[r.emailKey] = r;
  }
  for (const r of rows) {
    if (!r.emailKey || !(r.timestampClean instanceof Date)) continue;
    if (latestByEmail[r.emailKey] !== r) r.superseded = 'SUPERSEDED';
  }
}

function annotateFinalFlag_(rows) {
  for (const r of rows) {
    const needsReview =
      r.joinedClean === 'REVIEW' ||
      r.phoneClean  === 'REVIEW' ||
      r.timestampClean === 'REVIEW' ||
      r.parkClean   === 'REVIEW' ||
      r.dupEmail  !== '' ||
      r.dupNameTs !== '';
    r.finalFlag = needsReview ? 'REVIEW' : 'OK';
  }
}

// ---------- Output ----------

const CLEANED_HEADERS = [
  'RawRow',
  'Timestamp (raw)', 'Name (raw)', 'Email (raw)',
  'JoinedBefore (raw)', 'Phone (raw)', 'PreferredPark (raw)',
  'JoinedBefore (clean)', 'Phone (clean)', 'Timestamp (clean)', 'PreferredPark (clean)',
  'EmailKey', 'NameKey',
  'DupEmail', 'DupNameTime', 'Superseded',
  'FinalFlag',
];

