// ---------- Utilities ----------

/**
 * Return a blank sheet with the given name. If it exists, clear it
 * (preserving the tab/position). If not, create it.
 * Never touches the Raw sheet.
 */
function resetSheet_(ss, name) {
  if (name === RAW_SHEET) throw new Error('Refusing to reset the Raw sheet.');
  let sheet = ss.getSheetByName(name);
  if (sheet) {
    sheet.clear();            // clears values and formats
    sheet.clearNotes();
